import{_ as t,a}from"./chunks/catalog-graph.CJH_PNkf.js";import{_ as o,o as r,c as n,O as s}from"./chunks/framework.4XV3vnnU.js";const f=JSON.parse('{"title":"The Portal","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/portal.md","filePath":"documentation/portal.md","lastUpdated":1793117788000}'),i={name:"documentation/portal.md"};function l(d,e,h,p,c,g){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="the-portal" tabindex="-1">The Portal <a class="header-anchor" href="#the-portal" aria-label="Permalink to &quot;The Portal&quot;">​</a></h1><p>The portal is where users explore the catalog. After logging in, the left navigation shows the Overview, the Plugins page, the catalogs and the Explore section with the Tech Radar.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Overview lists every catalog as a card with a short description. A search box filters the cards. Click a card to open that catalog.</p><h2 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to &quot;Catalogs&quot;">​</a></h2><p>Each catalog is a viewpoint on the graph: a table of nodes of one or more kinds, fed by a defined set of plugins.</p><table tabindex="0"><thead><tr><th>Catalog</th><th>Shows</th><th>Fed by</th></tr></thead><tbody><tr><td>Model Catalog</td><td><code>model</code> nodes</td><td>litellm, mlflow, bedrock</td></tr><tr><td>Inference Endpoints Catalog</td><td><code>inference_endpoint</code> nodes</td><td>litellm, bedrock</td></tr><tr><td>MCP Catalog</td><td><code>mcp_server</code> nodes with their <code>mcp_tool</code> nodes</td><td>mcp-servers, litellm</td></tr><tr><td>Dataset Catalog</td><td><code>dataset</code> nodes</td><td>openmetadata</td></tr><tr><td>Software Catalog</td><td><code>deployment</code> and <code>service</code> nodes</td><td>depl-calls-svc, depl-uses-litellm, fluxcd</td></tr></tbody></table><p>A catalog page has a kind selector when it covers several kinds, and a <strong>Plugins &amp; Ingestion</strong> dialog that runs the plugins feeding this catalog. The table columns come from the properties the plugins report. Rows are clickable and open the detail page.</p><p><img src="'+t+'" alt="Catalog explorer listing models with their properties"></p><h2 id="detail-page" tabindex="-1">Detail page <a class="header-anchor" href="#detail-page" aria-label="Permalink to &quot;Detail page&quot;">​</a></h2><p>The detail page of a node has these parts:</p><ul><li><strong>Graph</strong>: the node and its relations, rendered as an interactive graph. Neighbouring nodes can be opened by clicking them.</li><li><strong>Properties</strong>: every property reported for this node, grouped by the plugin that reported it. When several plugins know the same node, each plugin&#39;s claim is shown separately.</li><li><strong>Related nodes</strong>: a section specific to the kind. An MCP server lists the tools it exposes. An inference endpoint shows the model it serves, and a model shows the endpoints serving it.</li><li><strong>Metrics</strong>: inference endpoints from LiteLLM and Bedrock show panels with request, token and latency metrics, queried from Prometheus through the UI with the user&#39;s token.</li></ul><p><img src="'+a+'" alt="Graph view of a catalog entry and its neighbours"></p><h2 id="plugins-page" tabindex="-1">Plugins page <a class="header-anchor" href="#plugins-page" aria-label="Permalink to &quot;Plugins page&quot;">​</a></h2><p>The Plugins page lists every plugin the catalog knows, with its schedule in a readable form (or &quot;Not scheduled&quot; for plugins that only run on demand) and the result of its latest run: running, succeeded with the number of nodes and relations, or failed with the error message. <strong>Run All Plugins</strong> starts every plugin, and each row has a button to run one plugin. The refresh button reloads the status while runs are in progress.</p><p>A failed run leaves the catalog unchanged. The previous snapshot of that plugin stays visible, so a temporary outage of a source system does not empty a catalog.</p><h2 id="tech-radar" tabindex="-1">Tech Radar <a class="header-anchor" href="#tech-radar" aria-label="Permalink to &quot;Tech Radar&quot;">​</a></h2><p>The Tech Radar under Explore renders the organization&#39;s technology decisions and links entries to the models and endpoints in the catalog. See <a href="/pr-preview/pr-12/documentation/tech-radar">Tech Radar</a>.</p><h2 id="standalone-ui" tabindex="-1">Standalone UI <a class="header-anchor" href="#standalone-ui" aria-label="Permalink to &quot;Standalone UI&quot;">​</a></h2><p>During development, the UI can be opened without the portal shell. In the local environment it is forwarded to port 3001. Login still goes through Keycloak, and the portal remains the entry point for users.</p>',20)])])}const b=o(i,[["render",l]]);export{f as __pageData,b as default};
